INSERT INTO feature VALUES('circuit-algebras','rewriting','Circuit algebras',NULL,'partial','unique','dependent provers','A circuit rule''s body reads as a monogamous acyclic wiring, matched by embedding with a convexity check and compared by its diagram normal form; a wheel''s feed is kept beside its cut-open wiring and guarded by an observation. A model of a theory holding a circuit rule is refused, so no wheel runs yet.','theory-circuit-algebras','corpus/model/circuit/circuit-rule-block.gandr corpus/pathological/circuit/circuit-feed-wheel.gandr corpus/model/circuit/circuit-feed-wheel.gandr corpus/pathological/circuit/circuit-feed-wheel-run.gandr','corpus/ledger/features/circuit-algebras.gandr','#1323');
